func:
node.warn("Commande RPI reçue");

// Parsing JSON MQTT
if (typeof msg.payload === "string") {
    try {
        msg.payload = JSON.parse(msg.payload);
    } catch (e) {
        node.error("JSON invalide : " + e.message);
        return null;
    }
}

const data = msg.payload;

// Vérification champs minimum
if (!data.rpiId || !data.badgeUid || !data.command) {
    node.error("Payload incomplet");
    return null;
}

// Nettoyage badge UID (caractères STX/ETX + espaces éventuels)
data.badgeUid = data.badgeUid
    .replace(/[\u0002\u0003]/g, '')
    .trim();

msg.receivedPayload = msg.payload;
msg.command = data.command;

return msg;

const rpiId = msg.receivedPayload.rpiId;

msg.rpiId = rpiId;

msg.payload = [
    {
        $match: {
            rpiId: rpiId
        }
    },
    {
        // on relie l'_id du raspberry (dans "raspberrypi")
        // au champ "rpiId" présent dans chaque document "tables"
        $lookup: {
            from: "tables",
            localField: "_id",
            foreignField: "rpiId",
            as: "table"
        }
    },
    {
        $unwind: "$table"
    },
    {
        // Filtre final : le rpi doit être actif ET la table occupée
        $match: {
            statut: "actif",
            "table.statut": "occupee"
        }
    },
    {
        // On ne garde que les champs utiles
        $project: {
            _id: 0,
            rpiId: 1,
            nom: 1,
            emplacement: 1,
            tableNumero: "$table.numero",
            tableStatut: "$table.statut"
        }
    }
];

return msg;

// Vérification du résultat MongoDB

msg.checkRpiSuccess = false;

if (!msg.payload || msg.payload.length === 0) {
    msg.payload = {
        success: false,
        error: "Raspberry Pi inconnu, inactif ou table non occupée",
        rpiId: msg.rpiId || null
    };

    // Optionnel : pour un traitement d'erreur MQTT
    msg.error = true;

    return msg;
}

// Success
msg.checkRpiSuccess = true;
msg.checkRpi = msg.payload[0];
node.warn("checkRpi" + msg.checkRpi);

msg.payload = {
    success: true,
    message: "Raspberry Pi valide et table occupée",
    data: msg.payload[0]
};

return msg;

const badgeUid = msg.receivedPayload.badgeUid;

msg.badgeUid = badgeUid;
node.warn("my warning " + badgeUid);

msg.payload = [
    {
        $match: {
            badgeUid: badgeUid
        }
    },
    {
        // on relie l'_id du raspberry (dans "raspberrypi")
        // au champ "rpiId" présent dans chaque document "tables"
        $lookup: {
            from: "visites",
            localField: "_id",
            foreignField: "badgeId",
            as: "visite"
        }
    },
    {
        $unwind: "$visite"
    },
    {
        // Filtre final
        $match: {
            statut: "attribue",
            "visite.statut": "ouverte"
        }
    },
    {
        // On ne garde que les champs utiles
        $project: {
            _id: 0,
            badgeUid: 1,
            badgeId: "$_id",
            visiteId: "$visite._id",
            clientId: "$visite.clientId",
            token: "$visite.token",
            tableNumero: "$visite.tableNumero",
            dateArrivee: "$visite.dateArrivee",
            statutVisite: "$visite.statut"
        }
    }
];

return msg;

// Vérification du résultat MongoDB
msg.checkBadgeSuccess = false;

if (!msg.payload || msg.payload.length === 0) {
    msg.payload = {
        success: false,
        error: "Badge non attribué, ou visite non ouverte",
        rpiId: msg.rpiId || null
    };
    msg.error = true;
    return msg;
}

// Success
msg.checkBadgeSuccess = true;

msg.checkBadge = msg.payload[0];
node.warn("checkBadge" + msg.checkBadge);

msg.payload = {
    success: true,
    message: "Badge valide et visite ouverte",
    data: msg.payload[0]
};

return msg;

if (!msg.checkRpiSuccess || !msg.checkBadgeSuccess || msg.waitingOrderAlreadyExistsForThisVisit){
    node.warn("smartcheers - error" + msg.checkRpiSuccess + msg.checkBadgeSuccess);
    msg.error = true;
    return msg;
}

node.warn("valid");

const command = msg.command;
const produitIds = command.map(c => c.produitId);

msg.payload = [
    { $match: { produitId: { $in: produitIds } } },
    {
        // suppose une collection "categories" contenant le champ "poste" (bar/cuisine/...)
        $lookup: {
            from: "categories_produits",
            localField: "categorieId",
            foreignField: "_id",
            as: "categorie"
        }
    },
    { $unwind: { path: "$categorie", preserveNullAndEmptyArrays: true } },
    {
        $project: {
            _id: 0,
            produitId: 1,
            nom: 1,
            prix: 1,
            disponible: 1,
            poste: "$categorie.poste"
        }
    }
];

return msg;

flow.set("checkBadgeSuccess", false)
flow.set("checkRpiSuccess", false)

msg.error = false;

return msg;

if(msg.error){
    return msg;
}

const produits = msg.payload;
const command = msg.command;

const produitsMap = {};
produits.forEach(p => { produitsMap[p.produitId] = p; });

let montantTotal = 0;
const lignes = [];

for (const item of command) {
    const produit = produitsMap[item.produitId];

    if (!produit) {
        msg.payload = { success: false, error: "Produit inconnu : " + item.produitId };
        msg.error = true;
        return msg;
    }
    if (produit.disponible === false) {
        msg.payload = { success: false, error: "Produit indisponible : " + produit.nom };
        msg.error = true;
        return msg;
    }

    montantTotal += produit.prix * item.quantite;

    lignes.push({
        produitId: item.produitId,
        produitNomSnapshot: produit.nom,
        quantite: item.quantite,
        prixUnitaireSnapshot: produit.prix,
        statutPreparation: "attente",
        poste: produit.poste || "bar"
    });
}

msg.payload = {
    visiteId: msg.checkBadge ? msg.checkBadge.visiteId : null,
    employeId: null,
    dateCommande: new Date(),
    statut: "en_attente",
    montantTotal: montantTotal,
    source: "rpi",
    lignes: lignes
};

return msg;

var waitingOrderAlreadyExistsForThisVisit = true;
if(msg.payload == 0){
    waitingOrderAlreadyExistsForThisVisit = false;
}

msg.waitingOrderAlreadyExistsForThisVisit = waitingOrderAlreadyExistsForThisVisit;

return msg;

var orderId = msg.payload[0]._id;
var rpiId = msg.checkRpi.rpiId;

msg.payload = {
    success: !msg.error,
    rpiId: rpiId,
    orderId: orderId
};

return msg;
